import hashlib, json

def schema_hash(tool):
    pinned = {"name":tool.get("name"),"description":tool.get("description", ""),"inputSchema":tool.get("inputSchema") or {}}
    raw = json.dumps(pinned, sort_keys=True, separators=(",", ":"), ensure_ascii=True).encode()
    return "sha256:" + hashlib.sha256(raw).hexdigest()

def valid(tool, declared):
    return bool(declared) and schema_hash(tool) == declared

